'use client';

import { useState } from 'react';
import { Download } from 'lucide-react';
import { apiFetchFile } from '@/services/api';
import { ImportType } from '@/types/api';
import { Button } from '@/components/ui/button';
import { downloadTextFile } from '@/lib/download';

export interface DownloadTemplateButtonProps {
  type: ImportType;
  label?: string;
  variant?: 'primary' | 'outline' | 'ghost';
  size?: 'sm' | 'md' | 'lg';
}

/**
 * Downloads the CSV template for an import type. The file is generated by the
 * API so the template always matches the validation rules.
 */
export function DownloadTemplateButton({
  type,
  label = 'Download template',
  variant = 'outline',
  size = 'sm',
}: DownloadTemplateButtonProps) {
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const download = async () => {
    setPending(true);
    setError(null);
    try {
      const file = await apiFetchFile(`/pharmacy/imports/templates/${type}`);
      downloadTextFile(file.filename, file.content, file.contentType);
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : 'Unable to download the template.');
    } finally {
      setPending(false);
    }
  };

  return (
    <div>
      <Button variant={variant} size={size} onClick={download} disabled={pending}>
        <Download className="mr-2 h-4 w-4" aria-hidden="true" />
        {pending ? 'Preparing…' : label}
      </Button>
      {error ? <p className="mt-1 text-xs text-danger">{error}</p> : null}
    </div>
  );
}
